; Function SetRAMBank flags 0x00000200 __smallc 
; void SetRAMBank()
	C_LINE	6,"128k.h::SetRAMBank::0::1"
._SetRAMBank
	.SetRAMBank
			ld	a, b
			or	a
			jp	z, restISR
			xor	a
			ld	i, a
			jp	keepGoing
	.restISR
			ld	a, $f0
			ld	i, a
	.keepGoing
			ld	a, 16
			or	b
			ld	bc, $7ffd
			out (C), a
	ret


